const search=document.querySelector('.search');
if(search){let category=new URLSearchParams(location.search).get('category')||'전체';const field=document.querySelector('#search');field.value=new URLSearchParams(location.search).get('q')||'';const cards=[...document.querySelectorAll('.guide-card')];const buttons=[...document.querySelectorAll('[data-filter]')];if(!buttons.some(b=>b.dataset.filter===category))category='전체';function filter(){let n=0;const term=field.value.trim().toLocaleLowerCase();for(const card of cards){const show=(category==='전체'||card.dataset.category===category)&&card.dataset.search.toLocaleLowerCase().includes(term);card.hidden=!show;if(show)n++}for(const b of buttons){const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}document.querySelector('#empty').hidden=n>0;document.querySelector('#results-status').textContent=term||category!=='전체'?`${n}개의 안내서를 찾았어요`:''}buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filter()}));field.addEventListener('input',filter);search.addEventListener('submit',e=>{e.preventDefault();filter();document.querySelector('#guides').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})});document.querySelector('#reset-search').addEventListener('click',()=>{field.value='';category='전체';filter();field.focus()});filter()}
